SID = "g5-reviewer-447"


def run(*a):
    p = subprocess.run([sys.executable, E, "--file", F, *a, "--session-id", SID],
                       capture_output=True, text=True, encoding="utf-8")
    out = (p.stdout or "").strip()[:160] + (p.stderr or "").strip()[:200]
    print(f"    exit={p.returncode} {out}")
    return p.returncode


